import type { Debounced, Throttled, Memoized } from '../types';
/**
 * Creates a debounced function
 * @param fn - Function to debounce
 * @param delay - Delay in milliseconds
 * @param options - Debounce options
 * @returns Debounced function
 */
export declare function debounce<T extends (...args: never[]) => unknown>(fn: T, delay?: number, options?: {
    leading?: boolean;
    trailing?: boolean;
}): Debounced<T>;
/**
 * Creates a throttled function
 * @param fn - Function to throttle
 * @param interval - Interval in milliseconds
 * @param options - Throttle options
 * @returns Throttled function
 */
export declare function throttle<T extends (...args: never[]) => unknown>(fn: T, interval?: number, options?: {
    leading?: boolean;
    trailing?: boolean;
}): Throttled<T>;
/**
 * Creates a memoized function
 * @param fn - Function to memoize
 * @param keyResolver - Custom key resolver
 * @returns Memoized function
 */
export declare function memoize<T extends (...args: never[]) => unknown>(fn: T, keyResolver?: (...args: Parameters<T>) => string): Memoized<T>;
/**
 * Creates a function that can only be called once
 * @param fn - Function to wrap
 * @returns Function that executes only once
 */
export declare function once<T extends (...args: never[]) => unknown>(fn: T): T;
/**
 * Creates a function that delays execution
 * @param fn - Function to delay
 * @param wait - Delay in milliseconds
 * @returns Delayed function
 */
export declare function delay<T extends (...args: never[]) => unknown>(fn: T, wait: number): (...args: Parameters<T>) => Promise<ReturnType<T>>;
/**
 * Creates a function that retries on failure
 * @param fn - Function to retry
 * @param retries - Number of retries
 * @param delayMs - Delay between retries
 * @returns Retrying function
 */
export declare function retry<T extends (...args: never[]) => Promise<unknown>>(fn: T, retries?: number, delayMs?: number): T;
/**
 * Composes functions from right to left
 * @param fns - Functions to compose
 * @returns Composed function
 */
export declare function compose<T>(...fns: ((arg: T) => T)[]): (arg: T) => T;
/**
 * Pipes functions from left to right
 * @param fns - Functions to pipe
 * @returns Piped function
 */
export declare function pipe<T>(...fns: ((arg: T) => T)[]): (arg: T) => T;
/**
 * Curries a function
 * @param fn - Function to curry
 * @returns Curried function
 */
export declare function curry<T extends (...args: never[]) => unknown>(fn: T): (...args: unknown[]) => unknown;
/**
 * Partially applies arguments to a function
 * @param fn - Function to partially apply
 * @param args - Arguments to apply
 * @returns Partially applied function
 */
export declare function partial<T extends (...args: never[]) => unknown>(fn: T, ...args: unknown[]): (...moreArgs: unknown[]) => ReturnType<T>;
/**
 * Negates a predicate function
 * @param fn - Predicate function
 * @returns Negated function
 */
export declare function negate<T extends (...args: never[]) => boolean>(fn: T): T;
/**
 * Flips function argument order
 * @param fn - Function to flip
 * @returns Flipped function
 */
export declare function flip<A, B, R>(fn: (a: A, b: B) => R): (b: B, a: A) => R;
/**
 * Creates a function that calls multiple functions
 * @param fns - Functions to call
 * @returns Function that calls all
 */
export declare function over<T extends (...args: never[]) => unknown>(...fns: T[]): (...args: Parameters<T>) => ReturnType<T>[];
/**
 * Creates a function that checks if all predicates pass
 * @param fns - Predicate functions
 * @returns Combined predicate
 */
export declare function allPass<T extends (...args: never[]) => boolean>(...fns: T[]): (...args: Parameters<T>) => boolean;
/**
 * Creates a function that checks if any predicate passes
 * @param fns - Predicate functions
 * @returns Combined predicate
 */
export declare function anyPass<T extends (...args: never[]) => boolean>(...fns: T[]): (...args: Parameters<T>) => boolean;
/**
 * Creates a function with a fixed this context
 * @param fn - Function to bind
 * @param context - This context
 * @returns Bound function
 */
export declare function bind<T extends (...args: never[]) => unknown>(fn: T, context: unknown): T;
/**
 * Creates an async version of a function
 * @param fn - Function to wrap
 * @returns Async function
 */
export declare function asyncify<T extends (...args: never[]) => unknown>(fn: T): (...args: Parameters<T>) => Promise<ReturnType<T>>;
/**
 * Wraps function with try-catch
 * @param fn - Function to wrap
 * @param fallback - Fallback value on error
 * @returns Safe function
 */
export declare function tryCatch<T extends (...args: never[]) => unknown>(fn: T, fallback: ReturnType<T>): T;
/**
 * Creates a function that limits concurrent calls
 * @param fn - Async function
 * @param limit - Concurrency limit
 * @returns Limited function
 */
export declare function limit<T extends (...args: never[]) => Promise<unknown>>(fn: T, limitNum: number): T;
/**
 * Creates a function that times execution
 * @param fn - Function to time
 * @param label - Console label
 * @returns Timed function
 */
export declare function timed<T extends (...args: never[]) => unknown>(fn: T, label?: string): T;
/**
 * Creates a function that logs arguments and result
 * @param fn - Function to log
 * @param label - Console label
 * @returns Logged function
 */
export declare function logged<T extends (...args: never[]) => unknown>(fn: T, label?: string): T;
/**
 * Creates a function that executes after n calls
 * @param n - Number of calls before execution
 * @param fn - Function to execute
 * @returns Delayed execution function
 */
export declare function after<T extends (...args: never[]) => unknown>(n: number, fn: T): T;
/**
 * Creates a function that executes only first n times
 * @param n - Maximum number of executions
 * @param fn - Function to execute
 * @returns Limited function
 */
export declare function before<T extends (...args: never[]) => unknown>(n: number, fn: T): T;
/**
 * Creates a function that wraps result in array
 * @param fn - Function to wrap
 * @returns Function returning array
 */
export declare function wrap<T extends (...args: never[]) => unknown>(fn: T): (...args: Parameters<T>) => [ReturnType<T>];
/**
 * Sleeps for specified duration
 * @param ms - Duration in milliseconds
 * @returns Promise that resolves after duration
 */
export declare function sleep(ms: number): Promise<void>;
/**
 * Creates a timeout promise
 * @param ms - Timeout in milliseconds
 * @param message - Error message
 * @returns Promise that rejects after timeout
 */
export declare function timeout<T>(ms: number, message?: string): Promise<T>;
/**
 * Races a promise against a timeout
 * @param promise - Promise to race
 * @param ms - Timeout in milliseconds
 * @param message - Error message
 * @returns Promise result or timeout error
 */
export declare function withTimeout<T>(promise: Promise<T>, ms: number, message?: string): Promise<T>;
/**
 * Creates an identity function
 * @returns Identity function
 */
export declare function identity<T>(): (value: T) => T;
/**
 * Creates a constant function
 * @param value - Value to return
 * @returns Constant function
 */
export declare function constant<T>(value: T): () => T;
/**
 * No-operation function
 */
export declare function noop(): void;
/**
 * Stub function returning true
 * @returns True
 */
export declare function stubTrue(): boolean;
/**
 * Stub function returning false
 * @returns False
 */
export declare function stubFalse(): boolean;
/**
 * Stub function returning empty array
 * @returns Empty array
 */
export declare function stubArray<T>(): T[];
/**
 * Stub function returning empty object
 * @returns Empty object
 */
export declare function stubObject<T extends object>(): T;
/**
 * Stub function returning empty string
 * @returns Empty string
 */
export declare function stubString(): string;
